import icontract
from typing import List, Tuple


@icontract.require(lambda x: x >= 0)
@icontract.require(lambda a: len(a) > 0)
@icontract.require(lambda x: x > 0)
@icontract.require(lambda a, x: x < len(a))
@icontract.ensure(lambda result: result[1] >= 0)
@icontract.ensure(lambda a, x, result: x <= result[1] < len(a))
@icontract.ensure(lambda a, x, result: all(a[i] <= result[0] for i in range(x)))
@icontract.ensure(lambda a, x, result: result[0] in a[:x])
@icontract.ensure(lambda a, result: not (result[1] < len(a) - 1) or all(a[i] < a[result[1]] for i in range(result[1])))
@icontract.ensure(lambda a, x, result: not all(a[i] <= result[0] for i in range(x, len(a))) or result[1] == len(a) - 1)
def onlineMax(a: List[int], x: int) -> Tuple[int, int]:
    m = a[0]
    for i in range(1, x):
        if a[i] > m:
            m = a[i]
    p = x
    while p < len(a) - 1 and a[p] <= m:
        p += 1
    return (m, p)
